function evaluateMath(expr) {
  if (!expr || typeof expr !== 'string') return null;
  let clean = expr
    .replace(/[₹$,]/g, '')
    .replace(/(\d+(?:\.\d+)?)%/g, '($1/100)')
    .replace(/\^/g, '**')
    .trim();

  const tokens = [];
  let i = 0;
  while (i < clean.length) {
    const ch = clean[i];
    if (/\s/.test(ch)) { i++; continue; }
    if (/\d/.test(ch) || (ch === '.' && /\d/.test(clean[i + 1] || ''))) {
      let numStr = '';
      while (i < clean.length && (/\d/.test(clean[i]) || clean[i] === '.')) {
        numStr += clean[i];
        i++;
      }
      tokens.push({ type: 'NUM', val: parseFloat(numStr) });
      continue;
    }
    if (ch === '*' && clean[i + 1] === '*') {
      tokens.push({ type: 'OP', val: '**' });
      i += 2;
      continue;
    }
    if ('+-*/()'.includes(ch)) {
      if (ch === '-' && (tokens.length === 0 || tokens[tokens.length - 1].type === 'OP' || (tokens[tokens.length - 1].type === 'PAREN' && tokens[tokens.length - 1].val === '('))) {
        tokens.push({ type: 'NUM', val: 0 });
        tokens.push({ type: 'OP', val: '-' });
        i++;
        continue;
      }
      if ('()'.includes(ch)) tokens.push({ type: 'PAREN', val: ch });
      else tokens.push({ type: 'OP', val: ch });
      i++;
      continue;
    }
    return null;
  }

  const prec = { '+': 1, '-': 1, '*': 2, '/': 2, '**': 3 };
  const assoc = { '+': 'L', '-': 'L', '*': 'L', '/': 'L', '**': 'R' };
  const outQueue = [];
  const opStack = [];

  for (const token of tokens) {
    if (token.type === 'NUM') {
      outQueue.push(token.val);
    } else if (token.type === 'OP') {
      while (opStack.length > 0) {
        const top = opStack[opStack.length - 1];
        if (top.type === 'OP') {
          if ((assoc[token.val] === 'L' && prec[token.val] <= prec[top.val]) ||
              (assoc[token.val] === 'R' && prec[token.val] < prec[top.val])) {
            outQueue.push(opStack.pop().val);
            continue;
          }
        }
        break;
      }
      opStack.push(token);
    } else if (token.type === 'PAREN') {
      if (token.val === '(') opStack.push(token);
      else {
        let foundOpen = false;
        while (opStack.length > 0) {
          const top = opStack.pop();
          if (top.type === 'PAREN' && top.val === '(') { foundOpen = true; break; }
          outQueue.push(top.val);
        }
        if (!foundOpen) return null;
      }
    }
  }

  while (opStack.length > 0) {
    const top = opStack.pop();
    if (top.type === 'PAREN') return null;
    outQueue.push(top.val);
  }

  const evalStack = [];
  for (const item of outQueue) {
    if (typeof item === 'number') {
      evalStack.push(item);
    } else {
      if (evalStack.length < 2) return null;
      const b = evalStack.pop();
      const a = evalStack.pop();
      let res = 0;
      switch (item) {
        case '+': res = a + b; break;
        case '-': res = a - b; break;
        case '*': res = a * b; break;
        case '/':
          if (b === 0) return 'Infinity';
          res = a / b;
          break;
        case '**': res = Math.pow(a, b); break;
        default: return null;
      }
      evalStack.push(res);
    }
  }

  if (evalStack.length !== 1) return null;
  const finalVal = evalStack[0];
  return typeof finalVal === 'number' ? (Math.round(finalVal * 100) / 100) : finalVal;
}

const inputObj = $input.item.json || {};
const rawExpr = inputObj.expression || inputObj.query || inputObj.operation || inputObj.input || '';
const exprLower = String(rawExpr).toLowerCase();

// 1. EMI Calculation
const isEmi = inputObj.operation === 'emi' || inputObj.operation === 'loan' || exprLower.includes('emi') || exprLower.includes('loan');
if (isEmi) {
  let P = parseFloat(inputObj.principal || inputObj.amount || inputObj.loanAmount || 0);
  let r = parseFloat(inputObj.rate || inputObj.interestRate || inputObj.apr || 0);
  let tenureYears = parseFloat(inputObj.tenure || inputObj.tenureYears || inputObj.years || 0);

  if (!P) {
    const pMatch = String(rawExpr).match(/(?:principal|loan|of|for|amount|₹|rs\.?)\s*:?\s*(\d+(?:,\d+)*(?:\.\d+)?)/i) || String(rawExpr).match(/(\d+(?:,\d+)*(?:\.\d+)?)\s*(?:loan|principal)/i);
    if (pMatch) {
      P = parseFloat(pMatch[1].replace(/,/g, ''));
    } else {
      const numbers = (String(rawExpr).match(/\b\d+(?:,\d+)*(?:\.\d+)?\b/g) || []).map(n => parseFloat(n.replace(/,/g, '')));
      const large = numbers.find(n => n >= 10000);
      if (large) P = large;
    }
  }
  if (!r) {
    const rMatch = String(rawExpr).match(/(\d+(?:\.\d+)?)\s*%/i) || String(rawExpr).match(/(?:rate|interest|apr)\s*:?\s*(\d+(?:\.\d+)?)/i);
    if (rMatch) r = parseFloat(rMatch[1]);
    else r = 8.5;
  }
  if (!tenureYears) {
    const tMatch = String(rawExpr).match(/(\d+)\s*(?:years?|yrs?)/i);
    if (tMatch) tenureYears = parseFloat(tMatch[1]);
    else tenureYears = 20;
  }

  if (P > 0 && r > 0 && tenureYears > 0) {
    const calcEmi = (pVal, rate, yrs) => {
      const R = (rate / 12) / 100;
      const N = yrs * 12;
      const emi = (pVal * R * Math.pow(1 + R, N)) / (Math.pow(1 + R, N) - 1);
      const totalPay = emi * N;
      return {
        tenureYears: yrs,
        monthlyEMI: Math.round(emi),
        totalInterest: Math.round(totalPay - pVal),
        totalPayment: Math.round(totalPay)
      };
    };

    const primary = calcEmi(P, r, tenureYears);
    const comparison = [15, 20, 25, 30].filter(y => y !== tenureYears).slice(0, 2).map(y => calcEmi(P, r, y));

    return {
      type: 'loan_emi',
      principal: P,
      annualRate: r,
      primaryOption: primary,
      comparisonOptions: comparison,
      guidance: `For ₹${P.toLocaleString('en-IN')} loan at ${r}% for ${tenureYears} years: Monthly EMI is ₹${primary.monthlyEMI.toLocaleString('en-IN')}. Total interest will be ₹${primary.totalInterest.toLocaleString('en-IN')}.`
    };
  }
}

// 2. 50/30/20 Budget Split
const isBudget = inputObj.operation === 'budget' || inputObj.operation === '50_30_20' || exprLower.includes('50/30/20') || exprLower.includes('budget');
if (isBudget) {
  let income = parseFloat(inputObj.income || inputObj.salary || inputObj.amount || 0);
  if (!income) {
    const incMatch = String(rawExpr).match(/(\d+(?:,\d+)*(?:\.\d+)?)/);
    if (incMatch) income = parseFloat(incMatch[1].replace(/,/g, ''));
  }
  if (income > 0) {
    const needs = Math.round(income * 0.50);
    const wants = Math.round(income * 0.30);
    const savings = Math.round(income * 0.20);
    return {
      type: 'budget_50_30_20',
      monthlyIncome: income,
      needs_50pct: needs,
      wants_30pct: wants,
      savings_20pct: savings,
      guidance: `For ₹${income.toLocaleString('en-IN')} income: Needs (50%) = ₹${needs.toLocaleString('en-IN')}, Wants (30%) = ₹${wants.toLocaleString('en-IN')}, Savings/Debt (20%) = ₹${savings.toLocaleString('en-IN')}.`
    };
  }
}

// 3. SIP Projection
const isSip = inputObj.operation === 'sip' || inputObj.operation === 'investment' || exprLower.includes('sip') || exprLower.includes('compound');
if (isSip) {
  let monthly = parseFloat(inputObj.monthlyInvestment || inputObj.sip || inputObj.amount || 0);
  let returnRate = parseFloat(inputObj.returnRate || inputObj.rate || inputObj.annualRate || 12);
  let years = parseFloat(inputObj.years || inputObj.tenureYears || inputObj.tenure || 10);

  if (!monthly) {
    const mMatch = String(rawExpr).match(/(\d+(?:,\d+)*(?:\.\d+)?)/);
    if (mMatch) monthly = parseFloat(mMatch[1].replace(/,/g, ''));
  }

  if (monthly > 0) {
    const iRate = (returnRate / 12) / 100;
    const nMonths = years * 12;
    const maturity = monthly * ((Math.pow(1 + iRate, nMonths) - 1) / iRate) * (1 + iRate);
    const invested = monthly * nMonths;
    const wealthGain = maturity - invested;

    return {
      type: 'sip_projection',
      monthlyInvestment: monthly,
      expectedReturnRate: returnRate,
      tenureYears: years,
      totalInvested: Math.round(invested),
      estimatedWealthGain: Math.round(wealthGain),
      maturityValue: Math.round(maturity),
      guidance: `₹${monthly.toLocaleString('en-IN')}/mo SIP for ${years} years at ${returnRate}%: Total invested ₹${Math.round(invested).toLocaleString('en-IN')}, Estimated maturity ₹${Math.round(maturity).toLocaleString('en-IN')} (Gain: ₹${Math.round(wealthGain).toLocaleString('en-IN')}).`
    };
  }
}

// 4. Safe Arithmetic Evaluation (No eval)
const mathRes = evaluateMath(rawExpr);
if (mathRes !== null) {
  return {
    type: 'arithmetic',
    expression: rawExpr,
    result: mathRes,
    guidance: `${rawExpr} = ${mathRes}`
  };
}

return {
  error: 'Could not compute. Provide math expression (e.g. 50000 * 0.20) or specify operation (emi, budget, sip).'
};

