const triggerData = $('Execute Workflow Trigger').first().json;

const query = (triggerData.query && triggerData.query.query) ? triggerData.query.query : (triggerData.query || triggerData.text || '');
const sheetId = (triggerData.query && triggerData.query.sheetId) ? triggerData.query.sheetId : (triggerData.sheetId || '');

let chatHistory = '';
try {
  chatHistory = $('Format Chat Memory').first()?.json?.chatHistory || '';
} catch(e) {}
if (!chatHistory || chatHistory === 'No history') {
  chatHistory = (triggerData.query && triggerData.query.chatHistory) ? triggerData.query.chatHistory : (triggerData.chatHistory || triggerData.historyJson || '');
}

let paramData = 'No insights available yet.';
try {
  const insightsNodes = $('Read Latest Param Insights').all();
  if (insightsNodes && insightsNodes.length > 0) {
    const lastRow = insightsNodes[insightsNodes.length - 1].json;
    if (lastRow && lastRow.insights) {
      paramData = lastRow.insights;
    } else if (lastRow && Object.keys(lastRow).length > 0) {
      paramData = lastRow.paramData || lastRow.insight || JSON.stringify(lastRow);
    }
  }
} catch(e) {}

let userMemories = 'No persistent memories recorded yet.';
try {
  const memNodes = $('Read User Memories').all();
  const activeMems = memNodes
    .map(n => n.json)
    .filter(m => m && (m.memoryId || m.content) && (m.status || 'active').toLowerCase() === 'active');
  if (activeMems.length > 0) {
    userMemories = '🧠 **Active User Memories & Stored Facts (' + activeMems.length + ' items):**\n' +
      activeMems.map(m => '• [' + (m.memoryType || 'NOTE').toUpperCase() + '] ' + m.content).join('\n');
  }
} catch(e) {}

return {
  json: {
    query: query || '',
    sheetId: sheetId || '',
    chatHistory: chatHistory || 'No history',
    paramData: paramData,
    userMemories: userMemories
  }
};

// Strip the 'Chatur says: ' prefix and return clean standard contract
const raw = $input.item.json.output || '';
const clean = raw.replace(/^chatur says:\s*/i, '').trim();

return {
  json: {
    success: true,
    agent: 'chatur',
    response: clean,
    error: null
  }
};

